"const sharp = require('sharp');
const path = require('path');

async function run() {
  const srcPath = 'public/PRODUTOS E LOGO/logo_monograma.png';
  const img = sharp(srcPath);
  const { data, info } = await img.raw().toBuffer({ resolveWithObject: true });

  const width = info.width;
  const height = info.height;
  const channels = info.channels; // should be 4 since it has alpha channel

  // 1. Generate White Logo
  const whiteData = Buffer.alloc(width * height * 4);
  for (let i = 0; i < width * height; i++) {
    const idx = i * channels;
    const destIdx = i * 4;

    // Check alpha
    const alpha = channels === 4 ? data[idx + 3] : 255;

    // We make all non-transparent pixels white
    whiteData[destIdx] = 255;     // R
    whiteData[destIdx + 1] = 255; // G
    whiteData[destIdx + 2] = 255; // B
    whiteData[destIdx + 3] = alpha; // A
  }

  await sharp(whiteData, {
    raw: {
      width,
      height,
      channels: 4
    }
  })
  .png()
  .toFile('public/PRODUTOS E LOGO/logo_monograma_branco.png');
  console.log('Saved: public/PRODUTOS E LOGO/logo_monograma_branco.png');

  // 2. Generate Gold Logo (#ffdb58 -> RGB 255, 219, 88)
  const goldData = Buffer.alloc(width * height * 4);
  for (let i = 0; i < width * height; i++) {
    const idx = i * channels;
    const destIdx = i * 4;

    // Check alpha
    const alpha = channels === 4 ? data[idx + 3] : 255;

    // We make all non-transparent pixels gold
    goldData[destIdx] = 255;     // R
    goldData[destIdx + 1] = 219; // G
    goldData[destIdx + 2] = 88;  // B
    goldData[destIdx + 3] = alpha; // A
  }

  await sharp(goldData, {
    raw: {
      width,
      height,
      channels: 4
    }
  })
  .png()
  .toFile('public/PRODUTOS E LOGO/logo_monograma_ouro.png');
  console.log('Saved: public/PRODUTOS E LOGO/logo_monograma_ouro.png');
}

run().catch(console.error);
"
